"""Replay values and derivatives generated by the archived GPTMini."""

import hashlib
import json
from pathlib import Path

import numpy as np
import torch
from torch.testing import assert_close

from diff_gpt.domain.model.gpt import GPT

FIXTURES = Path(__file__).resolve().parents[3] / "fixtures"


def test_gptmini_matches_archived_initialization_logits_and_gradients() -> None:
    """Keep exact seeded initialization and the historical forward/backward."""
    manifest = json.loads((FIXTURES / "gpt_mini_reference.json").read_text())
    path = FIXTURES / "gpt_mini_reference.npz"
    assert hashlib.sha256(path.read_bytes()).hexdigest() == manifest["fixture_sha256"]
    torch.manual_seed(manifest["seed"])
    model = GPT(**manifest["configuration"], use_checkpoint=False)
    with np.load(path, allow_pickle=False) as archive:
        tokens = torch.from_numpy(archive["tokens"])
        parameters = list(model.parameters())
        for index, parameter in enumerate(parameters):
            assert_close(
                parameter,
                torch.from_numpy(archive[f"parameter_{index}"]),
                rtol=0,
                atol=0,
            )
        logits = model(tokens)[0]
        assert_close(logits, torch.from_numpy(archive["logits"]), rtol=2e-5, atol=1e-6)
        logits.square().mean().backward()
        for index, parameter in enumerate(parameters):
            assert_close(
                parameter.grad,
                torch.from_numpy(archive[f"gradient_{index}"]),
                rtol=2e-4,
                atol=1e-6,
            )


def test_supervised_readout_preserves_logits_loss_and_gradients() -> None:
    """Reading the eight query positions preserves the masked objective."""
    torch.manual_seed(11)
    model = GPT(64, 16, block_size=8, n_layer=2, n_head=2, use_checkpoint=False)
    tokens = torch.randint(64, (2, 8))
    positions = torch.tensor([[3, 5, 7], [4, 5, 6]])
    targets = torch.randint(64, (2, 3))
    masked = torch.full_like(tokens, -100).scatter(1, positions, targets)
    full_logits, full_loss = model(tokens, masked)
    full_loss.backward()
    gradients = [parameter.grad.clone() for parameter in model.parameters()]
    model.zero_grad(set_to_none=True)
    logits, loss = model(tokens, targets, positions=positions)
    assert_close(logits, full_logits.gather(1, positions[..., None].expand(-1, -1, 64)))
    assert_close(loss, full_loss)
    loss.backward()
    for parameter, expected in zip(model.parameters(), gradients, strict=True):
        assert_close(parameter.grad, expected, rtol=2e-5, atol=1e-6)
